"use client";

import * as React from "react";
import * as stylex from "@stylexjs/stylex";
import { vlak, mq } from "./tokens.stylex";
import { rs } from "./rs";
import { Icon } from "./icons";

const styles = stylex.create({
	chip: {
		appearance: "none",
		boxSizing: "border-box",
		position: "relative",
		isolation: "isolate",
		display: "inline-flex",
		alignItems: "center",
		justifyContent: "center",
		gap: 8,
		minWidth: 48,
		minHeight: 48,
		padding: "8px 16px",
		borderWidth: 0,
		borderRadius: 8,
		backgroundColor: "transparent",
		color: vlak.ink,
		fontFamily: "Inter, -apple-system, BlinkMacSystemFont, sans-serif",
		fontSize: 14,
		fontWeight: 500,
		lineHeight: 1.4,
		cursor: { default: "pointer", ":disabled": "not-allowed" },
		opacity: { default: 1, ":disabled": 0.45 },
		outlineWidth: { default: null, ":focus-visible": 2 },
		outlineStyle: { default: null, ":focus-visible": "solid" },
		outlineColor: { default: null, ":focus-visible": vlak.ink },
		outlineOffset: 0,
		"::before": {
			content: '""',
			position: "absolute",
			zIndex: -1,
			inset: "8px 0",
			borderWidth: 1,
			borderStyle: "solid",
			borderColor: vlak.controlBorder,
			borderRadius: 8,
			backgroundColor: {
				default: vlak.paper,
				":hover": { default: null, [mq.hover]: vlak.controlFill },
			},
			transition: {
				default: "background-color 240ms cubic-bezier(.2,0,0,1)",
				[mq.reduce]: "none",
			},
		},
	},
	selected: {
		color: { default: vlak.paper, [mq.forcedColors]: "HighlightText" },
		fontWeight: 600,
		"::before": {
			backgroundColor: { default: vlak.ink, [mq.forcedColors]: "Highlight" },
			borderColor: { default: vlak.ink, [mq.forcedColors]: "Highlight" },
		},
	},
	icon: {
		display: "inline-flex",
		alignItems: "center",
		justifyContent: "center",
		flexShrink: 0,
		width: 20,
		height: 20,
	},
});
export interface AndroidChipProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement> {
	selected?: boolean;
	defaultSelected?: boolean;
	onSelectedChange?: (selected: boolean) => void;
	icon?: React.ReactNode;
}
export const AndroidChip = React.forwardRef<
	HTMLButtonElement,
	AndroidChipProps
>(function AndroidChip(
	{
		selected,
		defaultSelected = false,
		onSelectedChange,
		icon,
		onClick,
		className,
		style,
		children,
		type = "button",
		...props
	},
	ref,
) {
	const [inner, setInner] = React.useState(defaultSelected);
	const current = selected ?? inner;
	const sx = rs(
		["rs-android-chip", current && "rs-android-chip-selected", className],
		styles.chip,
		current && styles.selected,
	);
	const glyph = rs(["rs-android-chip-icon"], styles.icon);
	return (
		<button
			ref={ref}
			type={type}
			{...props}
			aria-pressed={current}
			onClick={(event) => {
				onClick?.(event);
				if (!event.defaultPrevented) {
					if (selected === undefined) setInner(!current);
					onSelectedChange?.(!current);
				}
			}}
			className={sx.className}
			style={{ ...sx.style, ...style }}
		>
			{(current || icon != null) && (
				<span {...glyph} aria-hidden="true">
					{current ? <Icon name="check" size={16} /> : icon}
				</span>
			)}
			{children}
		</button>
	);
});

/* ── android-chip: generated from packages/react/src/components/android-chip.tsx ── */
.rs-android-chip{appearance:none;box-sizing:border-box;position:relative;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;gap:8px;min-width:48px;min-height:48px;padding:8px 16px;border-width:0;border-radius:8px;background-color:transparent;color:var(--text);font-family:Inter, -apple-system, BlinkMacSystemFont, sans-serif;font-size:14px;font-weight:500;line-height:1.4;cursor:pointer;opacity:1;outline-offset:0}
.rs-android-chip:disabled{cursor:not-allowed;opacity:0.45}
.rs-android-chip:focus-visible{outline-width:2px;outline-style:solid;outline-color:var(--text)}
.rs-android-chip::before{content:"";position:absolute;z-index:-1;inset:8px 0;border-width:1px;border-style:solid;border-color:var(--control-border);border-radius:8px;background-color:var(--bg);transition:background-color 240ms cubic-bezier(.2,0,0,1)}
@media (hover: hover) and (pointer: fine){.rs-android-chip::before:hover{background-color:var(--control-fill)}}
@media (prefers-reduced-motion: reduce){.rs-android-chip::before{transition:none}}
.rs-android-chip-selected{color:var(--bg);font-weight:600}
.rs-android-chip-selected::before{background-color:var(--text);border-color:var(--text)}
@media (forced-colors: active){.rs-android-chip-selected{color:HighlightText}.rs-android-chip-selected::before{background-color:Highlight;border-color:Highlight}}
.rs-android-chip-icon{display:inline-flex;align-items:center;justify-content:center;flex-shrink:0;width:20px;height:20px}
